@startuml

class BusRoute {
  + RouteNumber : int
}

class Bus {
  + LicencePlate : string
  + IsInRepairShop : boolean
}

class Driver {
  + DriverID : int
  + Name : string
  + IsOnSickLeave : boolean
}

class Shift {
  + ShiftType : string
}

class Assignment {
  + Date : date
}

BusRoute "1" -- "*" Bus : assigned to
BusRoute "1" -- "*" Assignment : has
Bus "1" -- "*" Assignment : assigned to
Driver "1" -- "*" Assignment : assigned to
Assignment "1" -- "0..*" Shift : contains

@enduml

